(()=>{'use strict';const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)],queueKey='blacklake-v26-related-customers';let modal,parent;
function label(input){return input.closest('.kodo-new-form-item,.ant-form-item')?.querySelector('label')?.textContent.replace(/[\s*＊:：]/g,'');}
function close(){modal?.remove();modal=null;$('[data-v26-create-customer]',parent)?.focus();}
window.REVIEWED_V26_CUSTOMER_OPEN=layer=>{if(!window.REVIEWED_V26_CUSTOMER_ASSET)return;parent=layer;modal?.remove();modal=document.createElement('div');modal.dataset.reviewedV22Ui='';modal.dataset.v26Customer='';modal.style.cssText='position:fixed;inset:0;z-index:2147483640';modal.innerHTML='<div class="kodo-new-modal-mask"></div><div class="kodo-new-modal-wrap kodo-new-modal-centered">'+window.REVIEWED_V26_CUSTOMER_ASSET+'</div>';document.body.append(modal);const form=$('form',modal);if(form)form.onsubmit=e=>e.preventDefault();$$('input,textarea',modal).filter(e=>e.type!=='checkbox'&&!e.closest('.kodo-new-select,.ant-select')).forEach(e=>e.value='');$('input',modal)?.focus();};
function create(){const values={};$$('input,textarea',modal).forEach(e=>{const name=label(e);if(name&&!e.closest('.kodo-new-select,.ant-select'))values[name]=e.value.trim();});if(!values['客户名称']){window.DEMO_CONTEXT.toast('请输入客户名称');return;}if(values['收款期限']&&(!Number.isFinite(Number(values['收款期限']))||Number(values['收款期限'])<0)){window.DEMO_CONTEXT.toast('收款期限需为非负天数');return;}
 const id='DEMO-CUSTOMER-'+Date.now(),code=values['客户编号']||id;let queue,db;try{queue=JSON.parse(localStorage.getItem(queueKey)||'[]');db=JSON.parse(localStorage.getItem('blacklake-demo-v3-BL-09-09')||'null');}catch{window.DEMO_CONTEXT.toast('本地客户数据无法读取');return;}if([...queue,...(db?.records||[])].some(r=>r.fields?.['客户编号']===code)){window.DEMO_CONTEXT.toast('客户编号已存在');return;}const record={id,fields:{...values,'客户编号':code,'负责人':'所有人'},template:0};try{localStorage.setItem(queueKey,JSON.stringify([...queue,record]));}catch{window.DEMO_CONTEXT.toast('本地存储失败，客户未创建');return;}
 const item=$$('.kodo-new-form-item',parent).find(e=>(e.querySelector('.kodo-new-form-item-default-label')||e.querySelector('label'))?.textContent.replace(/[\s*＊:：]/g,'')==='客户');const input=item&&$('input',item);if(input){input.value=values['客户名称'];input.dataset.v26CustomerId=id;input.dataset.v26CustomerCode=code;}const display=$('.kodo-new-select-selection-item',item);if(display)display.textContent=values['客户名称'];close();window.DEMO_CONTEXT.toast('已创建本地演示客户并选入草稿；未提交黑湖');}
window.addEventListener('click',e=>{if(!e.target.closest?.('[data-v26-customer]'))return;e.preventDefault();e.stopImmediatePropagation();const button=e.target.closest('button');if(!button)return;const text=button.textContent.replace(/\s/g,'');if(button.getAttribute('aria-label')==='Close'||text==='取消')close();else if(text==='创建')create();else window.DEMO_CONTEXT.toast('此负责人选择深层操作尚未验收');},true);
window.addEventListener('input',e=>{if(e.target.closest?.('[data-v26-customer]'))e.stopImmediatePropagation();},true);
window.addEventListener('keydown',e=>{if(!modal)return;if(e.key==='Escape'){e.preventDefault();e.stopImmediatePropagation();close();}else if(e.target.closest?.('[data-v26-customer]')){e.stopImmediatePropagation();if(e.key==='Enter'){e.preventDefault();create();}}},true);
})();
